head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
    // 분류 Column(colIndex 0) 을 2 행 단위로 병합한다.
    target1.mergeCell({ "rowIndex" : 0, "colIndex" : 0, "rowSpan" : 2, "colSpan" : 1 });
    target1.mergeCell({ "rowIndex" : 2, "colIndex" : 0, "rowSpan" : 2, "colSpan" : 1 });
    target1.mergeCell({ "rowIndex" : 4, "colIndex" : 0, "rowSpan" : 2, "colSpan" : 1 });
};



// mergeCell 옵션을 바꿔 Excel 파일을 내려받는다.
scwin.download = function (strMergeCell) {
    WebSquare.util.multipleExcelDownload({
        common : {
            fileName : "mergeCell_" + strMergeCell,
            extension : "xls",
            mergeCell : strMergeCell,
            useHeader : "true"
        },
        excelInfo : [
            { gridId : "target1", sheetName : "제품목록", type : "0" }
        ]
    });

    scwin.setReturnValue("=====mergeCell = " + strMergeCell + " 로 다운로드=====");
    scwin.setReturnValue("    파일명 : mergeCell_" + strMergeCell + ".xls");
    scwin.setReturnValue("    내려받은 파일을 열어 (분류) 열의 병합 셀을 확인한다");
    scwin.setReturnValue("");
};



scwin.btn_mergeTrue_onclick = function (e) {
    scwin.download("true");
};

scwin.btn_mergeFalse_onclick = function (e) {
    scwin.download("false");
};
